      asset: { _type: "reference", _ref: "image-85913be8fcaad23f5cb1d29a34826930b3d34ad8-1600x1216-jpg" },
      alt: "Cinematic editorial composition exploring the synthetic visual perfection and uncanny valley of AI imagery",
      url: "/covers/ai-images-uncanny-valley-cover.webp",
